mapper.select:
SELECT d.id, d.dept_code, d.dept_name, d.parent_id, d.status, d.sort_no, d.created_at, d.updated_at, d.is_deleted AS isDeleted, d.deleted_at AS deletedAt, d.deleted_by AS deletedBy FROM sys_department d
AND (d.dept_name LIKE CONCAT('%', #{keyword}, '%') OR d.dept_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY d.sort_no ASC, d.id ASC LIMIT #{limit}

